import{_ as o,C as d,o as a,c as l,a2 as r,b as c,w as t,a as p,E as n,a3 as s}from"./chunks/framework.DZUUNQ77.js";const _=JSON.parse('{"title":"NativeLibraryHelperCompat · native 库抽取兼容","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/compat/native-library-helper-compat.md","filePath":"reference/helper/compat/native-library-helper-compat.md","lastUpdated":1784063681000}'),A={name:"reference/helper/compat/native-library-helper-compat.md"};function E(h,e,B,b,m,v){const i=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="nativelibraryhelpercompat-·-native-库抽取兼容" tabindex="-1">NativeLibraryHelperCompat · native 库抽取兼容 <a class="header-anchor" href="#nativelibraryhelpercompat-·-native-库抽取兼容" aria-label="Permalink to &quot;NativeLibraryHelperCompat · native 库抽取兼容&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/compat/NativeLibraryHelperCompat.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/compat/NativeLibraryHelperCompat.java</code></a></p></div><p><code>NativeLibraryHelperCompat</code> 对应 AOSP 的 <code>NativeLibraryHelper</code>，在安装虚拟 App 时从 APK 抽取对应 ABI 的 <code>.so</code> 共享库到 lib 目录，供目标 App 运行时加载。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>copyNativeBinaries(File apkFile, File sharedLibraryDir)</code></td><td>从 APK 抽取 .so 到目标目录，返回抽取数量</td></tr><tr><td><code>isApk64(String apk)</code></td><td>判断 APK 是否含 64 位 so</td></tr><tr><td><code>getABIsFromApk(String apk)</code></td><td>枚举 APK 内含的 ABI 集合（私有）</td></tr><tr><td><code>isVM64(Set&lt;String&gt; supportedABIs)</code></td><td>判断当前虚拟机是否 64 位（私有）</td></tr></tbody></table><h2 id="版本分支" tabindex="-1">版本分支 <a class="header-anchor" href="#版本分支" aria-label="Permalink to &quot;版本分支&quot;">​</a></h2><ul><li><code>copyNativeBinariesBeforeL</code> —— Android 5.0 之前用旧 <code>NativeLibraryHelper.copyNativeBinariesIfNeededLI</code>。</li><li><code>copyNativeBinariesAfterL</code> —— 5.0+ 用 <code>NativeLibraryHelper.copyNativeBinaries</code>（签名变了）。</li></ul><h2 id="abi-选择逻辑" tabindex="-1">ABI 选择逻辑 <a class="header-anchor" href="#abi-选择逻辑" aria-label="Permalink to &quot;ABI 选择逻辑&quot;">​</a></h2><ol><li><code>getABIsFromApk</code> 扫描 APK 内 <code>lib/&lt;abi&gt;/*.so</code>，得到 APK 支持的 ABI 集合。</li><li><code>isVM64</code> 用 <code>Build.CPU_ABI</code> / <code>Build.SUPPORTED_ABIS</code> 判断当前进程是 32 位还是 64 位虚拟机。</li><li>据此决定抽 32 位还是 64 位的 so，避免架构不匹配导致 <code>dlopen</code> 失败。</li></ol><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p><code>VAppManagerService.installPackage</code> 复制 APK 后调用 <code>copyNativeBinaries</code>，把 .so 抽到 <code>appDir/lib/</code>。运行时 <a href="./../../client/native-engine"><code>NativeEngine</code></a> 配置 <code>dlopen</code> 重定向到这个目录。</p><h2 id="安装时-so-抽取流" tabindex="-1">安装时 so 抽取流 <a class="header-anchor" href="#安装时-so-抽取流" aria-label="Permalink to &quot;安装时 so 抽取流&quot;">​</a></h2>',12)),(a(),c(s,null,{default:t(()=>[n(i,{id:"mermaid-104",class:"mermaid",graph:"flowchart%20TD%0A%20%20APK%5B%22APK%20%E6%96%87%E4%BB%B6%22%5D%20--%3E%20ABI%5B%22getABIsFromApk%3Cbr%2F%3E%E6%89%AB%E6%8F%8F%20lib%2F%3Cabi%3E%2F*.so%22%5D%0A%20%20ABI%20--%3E%20SET%5B%22APK%20%E6%94%AF%E6%8C%81%E7%9A%84%20ABI%20%E9%9B%86%E5%90%88%22%5D%0A%20%20SET%20--%3E%20V64%7B%22isVM64%3F%22%7D%0A%20%20V64%20--%3E%7C%22%E8%AF%BB%20Build.CPU_ABI%22%7C%20DEC%5B%22%E5%86%B3%E5%AE%9A%E6%8A%BD%2032%2F64%20%E4%BD%8D%20so%22%5D%0A%20%20DEC%20--%3E%20Q%7B%22API_LEVEL%3F%22%7D%0A%20%20Q%20--%3E%7C%225.0%20%E5%89%8D%22%7C%20OLD%5B%22copyNativeBinariesBeforeL%3Cbr%2F%3E%E6%97%A7%E7%AD%BE%E5%90%8D%22%5D%0A%20%20Q%20--%3E%7C%225.0%2B%22%7C%20NEW%5B%22copyNativeBinariesAfterL%3Cbr%2F%3E%E6%96%B0%E7%AD%BE%E5%90%8D%22%5D%0A%20%20OLD%20--%3E%20DIR%5B%22appDir%2Flib%2F*.so%22%5D%0A%20%20NEW%20--%3E%20DIR%0A%20%20DIR%20--%3E%20NE%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%20NativeEngine%3Cbr%2F%3Edlopen%20%E9%87%8D%E5%AE%9A%E5%90%91%E5%88%B0%20appDir%2Flib%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>架构判断错误会导致 <code>dlopen</code> 失败，所以 <code>isVM64</code> 必须读真实 <code>Build</code> 字段（不被伪造干扰）。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/VirtualXposed-skills/features/package-manager">包管理</a> 安装流程。</li><li><a href="./../../server/pm"><code>VAppManagerService</code></a>。</li><li><a href="./../../client/native-engine"><code>NativeEngine</code></a>：运行时 so 加载重定向。</li></ul>',3))])}const D=o(A,[["render",E]]);export{_ as __pageData,D as default};
